async (page) => {
  const input = page.getByPlaceholder('What needs to be done?');
  const out = {};
  await input.fill('walk the dog');
  await input.press('Enter');
  out.countTwo = await page.getByTestId('todo-count').textContent();
  // whitespace-only
  await input.fill('   ');
  await input.press('Enter');
  out.afterWhitespace = await page.getByTestId('todo-item').count();
  out.inputValueAfterWhitespace = await input.inputValue();
  // empty
  await input.fill('');
  await input.press('Enter');
  out.afterEmpty = await page.getByTestId('todo-item').count();
  // leading/trailing spaces
  await input.fill('  padded item  ');
  await input.press('Enter');
  out.titles = await page.getByTestId('todo-title').allTextContents();
  out.storageKeys = await page.evaluate(() => Object.keys(localStorage));
  out.storage = await page.evaluate(() => JSON.stringify(Object.fromEntries(Object.entries(localStorage))));
  return out;
}

