async (page) => {
  const out = {};
  const input = page.getByPlaceholder('What needs to be done?');
  out.inputAfterValidAdd = await input.inputValue();
  const items = page.getByTestId('todo-item');
  // toggle first item complete
  await items.filter({ hasText: 'buy milk' }).getByLabel('Toggle Todo').check();
  out.count = await page.getByTestId('todo-count').textContent();
  out.firstItemClass = await items.filter({ hasText: 'buy milk' }).getAttribute('class');
  out.clearCompletedVisible = await page.getByRole('button', { name: 'Clear completed' }).isVisible();
  // filters
  await page.getByRole('link', { name: 'Active' }).click();
  out.activeUrl = page.url();
  out.activeTitles = await page.getByTestId('todo-title').allTextContents();
  await page.getByRole('link', { name: 'Completed' }).click();
  out.completedUrl = page.url();
  out.completedTitles = await page.getByTestId('todo-title').allTextContents();
  out.footerOnCompleted = await page.getByTestId('todo-count').textContent();
  await page.getByRole('link', { name: 'All' }).click();
  out.allUrl = page.url();
  // toggle-all
  await page.getByLabel('Mark all as complete').check();
  out.afterToggleAllCount = await page.getByTestId('todo-count').textContent();
  out.toggleAllChecked = await page.getByLabel('Mark all as complete').isChecked();
  out.allToggles = await page.getByLabel('Toggle Todo').evaluateAll(els => els.map(e => e.checked));
  await page.getByLabel('Mark all as complete').uncheck();
  out.afterUntoggleAll = await page.getByLabel('Toggle Todo').evaluateAll(els => els.map(e => e.checked));
  return out;
}

