async (page) => {
  const out = {};
  const items = page.getByTestId('todo-item');
  const titles = page.getByTestId('todo-title');
  await items.filter({ hasText: 'buy milk' }).getByLabel('Toggle Todo').check();
  await page.getByRole('link', { name: 'Active' }).click();
  await page.waitForFunction(() => document.querySelectorAll('[data-testid="todo-title"]').length === 2);
  out.activeTitles = await titles.allTextContents();
  out.activeCount = await page.getByTestId('todo-count').textContent();
  await page.getByRole('link', { name: 'Completed' }).click();
  await page.waitForFunction(() => document.querySelectorAll('[data-testid="todo-title"]').length === 1);
  out.completedTitles = await titles.allTextContents();
  // selected class on filter link
  out.selected = await page.locator('.filters a.selected').textContent();
  // clear completed on completed filter
  await page.getByRole('button', { name: 'Clear completed' }).click();
  await page.waitForTimeout(300);
  out.afterClearOnCompletedTitles = await titles.allTextContents();
  out.afterClearUrl = page.url();
  out.clearBtnStillThere = await page.getByRole('button', { name: 'Clear completed' }).count();
  await page.getByRole('link', { name: 'All' }).click();
  await page.waitForTimeout(300);
  out.allTitles = await titles.allTextContents();
  out.countSingularCheck = await page.getByTestId('todo-count').textContent();
  return out;
}

