async (page) => {
  const out = {};
  const items = page.getByTestId('todo-item');
  const row = items.filter({ hasText: 'walk the dog' });
  await row.dblclick();
  out.rowClassEditing = await row.getAttribute('class');
  const edit = row.getByLabel('Edit');
  out.editValue = await edit.inputValue();
  out.editFocused = await edit.evaluate(e => e === document.activeElement);
  out.titleVisibleWhileEditing = await row.getByTestId('todo-title').isVisible();
  // Escape cancels
  await edit.fill('changed but cancelled');
  await edit.press('Escape');
  await page.waitForTimeout(200);
  out.afterEscape = await page.getByTestId('todo-title').allTextContents();
  out.classAfterEscape = await row.getAttribute('class');
  // Enter saves with trim
  await row.dblclick();
  await row.getByLabel('Edit').fill('   walk the cat   ');
  await row.getByLabel('Edit').press('Enter');
  await page.waitForTimeout(200);
  out.afterEnter = await page.getByTestId('todo-title').allTextContents();
  // blur saves?
  const row2 = items.filter({ hasText: 'walk the cat' });
  await row2.dblclick();
  await row2.getByLabel('Edit').fill('blurred value');
  await page.getByPlaceholder('What needs to be done?').click();
  await page.waitForTimeout(300);
  out.afterBlur = await page.getByTestId('todo-title').allTextContents();
  return out;
}

