async (page) => {
  const out = {};
  const input = page.getByPlaceholder('What needs to be done?');
  const items = page.getByTestId('todo-item');
  // duplicates + markup-ish text
  await input.fill('<b>bold</b> & "quoted"'); await input.press('Enter');
  await input.fill('gamma'); await input.press('Enter');
  await page.waitForTimeout(200);
  out.titles = await page.getByTestId('todo-title').allTextContents();
  out.markupRendered = await page.getByTestId('todo-title').filter({ hasText: 'bold' }).innerHTML();
  // toggle-all reflects individual toggles
  const toggleAll = page.getByLabel('Mark all as complete');
  out.toggleAllBefore = await toggleAll.isChecked();
  for (const cb of await page.getByLabel('Toggle Todo').all()) { if (!(await cb.isChecked())) await cb.check(); }
  await page.waitForTimeout(300);
  out.toggleAllAfterAllChecked = await toggleAll.isChecked();
  await items.filter({ hasText: 'gamma' }).first().getByLabel('Toggle Todo').uncheck();
  await page.waitForTimeout(300);
  out.toggleAllAfterOneUnchecked = await toggleAll.isChecked();
  // deep link
  await page.goto('https://demo.playwright.dev/todomvc/#/active');
  await page.waitForTimeout(400);
  out.deepLinkActive = await page.getByTestId('todo-title').allTextContents();
  out.deepLinkSelected = await page.locator('.filters a.selected').textContent();
  // filter survives reload
  await page.reload(); await page.waitForTimeout(400);
  out.afterReloadUrl = page.url();
  out.afterReloadTitles = await page.getByTestId('todo-title').allTextContents();
  // bogus hash
  await page.goto('https://demo.playwright.dev/todomvc/#/bogus');
  await page.waitForTimeout(400);
  out.bogusTitles = await page.getByTestId('todo-title').allTextContents();
  out.bogusSelected = await page.locator('.filters a.selected').count();
  return out;
}

